import pyomo.environ as pyo

DATA = {
    "routes": ["X1", "X2", "X3"],
    "cost": {"X1": 4, "X2": 5, "X3": 6},
    "upper_bound": {"X1": 1500, "X2": 1200, "X3": 800},
    "x1_x2_max": 2000,
    "x2_x3_min": 1000,
    "x1_minus_2x3": 500,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ROUTES = pyo.Set(initialize=d["routes"])

    def truck_bounds(m, r):
        return (0, d["upper_bound"][r])

    model.trucks = pyo.Var(
        model.ROUTES,
        within=pyo.NonNegativeIntegers,
        bounds=truck_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][r] * m.trucks[r] for r in m.ROUTES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def x1_x2_cap_rule(m):
        return m.trucks["X1"] + m.trucks["X2"] <= d["x1_x2_max"]

    model.x1_x2_cap = pyo.Constraint(rule=x1_x2_cap_rule)

    def x2_x3_demand_rule(m):
        return m.trucks["X2"] + m.trucks["X3"] >= d["x2_x3_min"]

    model.x2_x3_demand = pyo.Constraint(rule=x2_x3_demand_rule)

    def x1_x3_balance_rule(m):
        return m.trucks["X1"] - 2 * m.trucks["X3"] == d["x1_minus_2x3"]

    model.x1_x3_balance = pyo.Constraint(rule=x1_x3_balance_rule)

    return model


